                    }
                    ++it;

                    if(delimiter_end!= nullptr && delimiter_end!= delimiter_begin){ // close existing delimiter tag if open
                        while(!is_delimiter_open){
                            --delimiter_end;
                            is_delimiter_open = (*(--delimiter_end)) == '`'; // check if last character was opening tickmark
                        }
                        is_delimiter_open = false;
                        html += std::string("\n" + std::string(delimiter_begin, delimiter_end+1), '<', '>');
